      const th = clamp(thA.length > 1 ? thA[i] : thA[0], 0, 1);
      rpmSum += rpm; thSum += th;
      const inc = (rpm / 120) * dt * wobK;
      this.incS[i] = inc;
      ph += inc;
      if (ph >= 1) ph -= 1;
